<template>
  <view class="page">
    <view class="aurora one"></view><view class="aurora two"></view>
    <view class="topbar">
      <view class="brand"><text class="mark">DF</text><view><text class="brand-title">数字人工厂</text><text class="brand-sub">AI DIRECTED · COMFYUI POWERED</text></view></view>
      <view class="top-actions"><button class="service-status" :class="{online:health.ok}" @click="navigateTo('settings')"><text class="status-dot"></text>{{ healthText }}</button><button class="primary small" @click="navigateTo('create')">＋ 新建任务</button></view>
    </view>

    <view class="main-nav panel">
      <button v-for="item in navigation" :key="item.value" class="nav-button" :class="{active:viewMode===item.value}" @click="navigateTo(item.value)"><text class="nav-icon">{{ item.icon }}</text><text>{{ item.label }}</text><text v-if="item.value==='queue'&&activeTaskCount" class="nav-count">{{ activeTaskCount }}</text></button>
    </view>

    <view v-if="viewMode==='settings'" class="settings-shell">
      <view class="settings-heading"><text class="eyebrow">SYSTEM</text><text class="page-title">系统设置</text><text class="lead">集中管理 ComfyUI 和本地生产能力，新建任务时无需重复填写。</text></view>
    <view class="api-bar panel comfy-settings">
      <view><text class="label-title">ComfyUI 全局配置</text><text class="hint">保存一次，之后所有手动和队列任务统一使用该地址</text></view>
      <textarea v-model="appSettings.comfy_url" class="field url-field" :maxlength="-1" auto-height placeholder="http://127.0.0.1:8188"></textarea>
      <view class="inline">
        <button class="ghost small" @tap.stop="pasteComfyUrl">粘贴</button>
        <button class="ghost small" :disabled="comfyChecking" @tap.stop="checkComfy(appSettings.comfy_url,form.tts_engine)">{{ comfyChecking ? '检测中' : '检测' }}</button>
        <button class="primary small" :disabled="settingsSaving" @tap.stop="saveAppSettings">{{ settingsSaving ? '保存中' : '保存' }}</button>
      </view>
      <view v-if="comfyCheckResult" class="check-message global-check-message" :class="{success:comfyCheckOk,error:!comfyCheckOk&&!comfyChecking}">{{ comfyCheckResult }}</view>
    </view>
      <view class="settings-grid">
        <view class="panel setting-card"><text class="setting-icon">AI</text><view><text class="auto-run-title">AI 导演</text><text class="hint">{{ health.vision_enabled ? '视觉模型已配置' : '视觉模型尚未配置' }}</text></view><text class="setting-state" :class="{ok:health.vision_enabled}">{{ health.vision_enabled ? '正常' : '检查配置' }}</text></view>
        <view class="panel setting-card"><text class="setting-icon">W</text><view><text class="auto-run-title">Whisper CLI</text><text class="hint">{{ health.whisper_executable || '未检测到命令' }}</text></view><text class="setting-state" :class="{ok:health.asr_enabled}">{{ health.asr_enabled ? '正常' : '不可用' }}</text></view>
        <view class="panel setting-card"><text class="setting-icon">Q</text><view><text class="auto-run-title">生产队列</text><text class="hint">单 GPU 安全顺序执行</text></view><text class="setting-state ok">{{ health.queue_worker==='running' ? '运行中' : '已停止' }}</text></view>
      </view>
    </view>

    <view v-else-if="viewMode==='queue'" class="queue-page">
      <view class="page-heading"><view><text class="eyebrow">PRODUCTION</text><text class="page-title">任务队列</text><text class="lead">只保留等待、运行、失败和已取消任务；完成项目自动进入项目库。<text class="realtime-state" :class="{online:realtimeConnected}">{{ realtimeConnected ? '实时推送' : '低频轮询' }}</text></text></view><button class="ghost small" @click="loadTasks">刷新</button></view>
      <view class="queue-stats"><view class="panel stat-card"><text class="stat-value">{{ runningTaskCount }}</text><text class="hint">正在执行</text></view><view class="panel stat-card"><text class="stat-value">{{ queuedTaskCount }}</text><text class="hint">等待中</text></view><view class="panel stat-card danger"><text class="stat-value">{{ failedTaskCount }}</text><text class="hint">需要处理</text></view></view>
      <view v-if="!tasks.length" class="panel page-empty"><text class="empty-title">当前没有生产任务</text><text class="hint">新建任务并选择全自动一条龙后，会在这里看到执行状态。</text><button class="primary small" @click="navigateTo('create')">新建任务</button></view>
      <view v-else class="queue-list-main"><view v-for="task in tasks" :key="task.id" class="panel task-card-large" :class="`queue-${taskDisplayClass(task)}`" @click="openProject(task.project_id)"><view class="task-card-status"><text class="task-status-dot"></text><text>{{ statusName(task.display_status) }}</text></view><view class="task-card-content"><text class="task-card-title">{{ task.project_title }}</text><text class="hint">{{ taskStageName(task.stage) }} · {{ ttsEngineName(task.tts_engine) }}</text><view class="task-progress"><view :style="{width:`${Number(task.display_progress||0)}%`}"></view></view><view class="task-progress-copy"><text>{{ taskProgressText(task) }}</text><text>{{ Number(task.display_progress||0) }}%</text></view><text v-if="task.error" class="task-error-summary">{{ task.error.message || task.error }}</text></view><view class="task-card-actions"><button v-if="task.status==='QUEUED'||task.status==='RUNNING'" class="ghost small" @click.stop="cancelTask(task)">取消</button><button v-if="canRetryTask(task)" class="primary small" @click.stop="retryTask(task)">重试</button><button class="danger-button small" :disabled="task.deleting" @click.stop="deleteTask(task)">{{ task.deleting ? '删除中' : '删除' }}</button></view></view></view>
    </view>

    <view v-if="viewMode==='create'||viewMode==='projects'" class="shell" :class="{'create-shell':viewMode==='create'}">
      <view v-if="viewMode==='projects'" class="sidebar panel">
        <view class="section-head"><text>项目库</text><text class="refresh" @click="loadProjects">↻</text></view>
        <view v-if="!projects.length" class="empty">还没有项目</view>
        <view v-for="item in projects" :key="item.id" class="project-item" :class="{active: current?.id === item.id}" @click="openProject(item.id)">
          <view class="project-info"><text class="project-name">{{ item.title }}</text><text class="project-meta">{{ statusName(item.status) }} · {{ item.id }}</text></view>
          <button class="project-delete" @click.stop="deleteProject(item)">删除</button>
        </view>
      </view>

      <view class="workspace">
        <view v-if="viewMode==='projects'&&!current" class="project-library"><view class="page-heading"><view><text class="eyebrow">LIBRARY</text><text class="page-title">项目库</text><text class="lead">查看已完成项目或继续编辑生产中的项目。</text></view><button class="primary small" @click="navigateTo('create')">＋ 新建任务</button></view><view v-if="!projects.length" class="panel page-empty"><text class="empty-title">还没有项目</text><text class="hint">完成第一次任务提交后，项目会出现在这里。</text></view><view v-else class="project-grid"><view v-for="item in projects" :key="`grid-${item.id}`" class="panel project-card" @click="openProject(item.id)"><view class="project-card-cover"><text>DF</text></view><view class="project-card-copy"><text class="task-card-title">{{ item.title }}</text><text class="hint">{{ statusName(item.status) }}</text><text class="project-id">{{ item.id }}</text></view><button class="project-delete" @click.stop="deleteProject(item)">删除</button></view></view></view>
        <view v-if="viewMode==='create'" class="panel create-card">
          <text class="eyebrow">PHASE TWO</text><text class="hero">从一张照片，到完整口播视频</text>
          <text class="lead">本地 Whisper 精确对齐，AI 设计每 4 秒连续动作，ComfyUI 负责声音与视频生成。</text>
          <view class="create-section">
            <view class="create-section-head"><view><text class="section-index">01</text><text class="plan-title">任务内容</text></view><text class="hint">{{ scriptSummary }}</text></view>
          <view><text class="label">项目名称</text><textarea :value="form.title" class="field project-title-field" maxlength="100" auto-height @input="setProjectTitle"></textarea></view>
          <view><text class="label">原始口播文案</text><textarea v-model="form.original_script" class="textarea script-input" :maxlength="-1" @input="syncCreateTitle"></textarea></view>
          </view>
          <view class="create-section">
            <view class="create-section-head"><view><text class="section-index">02</text><text class="plan-title">数字人与声音素材</text></view><text class="hint">先选择音频流程，再提交对应参考音频</text></view>
          <view><text class="label">音频生成流程</text><view class="engine-options"><button class="engine-option" :class="{active:!form.tts_engine||form.tts_engine==='indextts2_legacy'}" @click="form.tts_engine='indextts2_legacy'"><text>IndexTTS2 基础情感版</text><text class="hint">indextts2-basic_emo_api.json · AI 情绪向量</text></button><button class="engine-option" :class="{active:form.tts_engine==='indextts2_voice_clone'}" @click="form.tts_engine='indextts2_voice_clone'"><text>IndexTTS2 音色与情感克隆版</text><text class="hint">indextts2-voice-clone_api.json · 音色＋情感双参考</text></button></view></view>
          <view class="uploads">
            <view class="upload-box image-upload" :class="{selected:Boolean(imagePath)}" @click="chooseImage">
              <image v-if="imagePath" class="upload-preview" :src="imagePath" mode="aspectFill" />
              <view class="upload-copy"><text>数字人图片</text><text v-if="imagePath" class="upload-status">✓ 已选择</text><text class="hint file-name">{{ imageFileName || '点击选择；不选使用默认图片' }}</text></view>
            </view>
            <view class="upload-box" :class="{selected:Boolean(voicePath)}" @click="chooseVoice">
              <text class="upload-icon">♪</text><text>音色参考音频</text><text v-if="voicePath" class="upload-status">✓ 已选择</text><text class="hint file-name">{{ voiceFileName || '点击选择；不选使用默认音色' }}</text>
            </view>
            <view v-if="form.tts_engine==='indextts2_voice_clone'" class="upload-box emotion-reference" :class="{selected:Boolean(emotionVoicePath)}" @click="chooseEmotionVoice">
              <text class="upload-icon">♫</text><text>情感参考音频</text><text v-if="emotionVoicePath" class="upload-status">✓ 已选择</text><text class="hint file-name">{{ emotionVoiceFileName || '新版必选；用于复制语气和情感' }}</text>
            </view>
          </view>
          </view>
          <view class="create-section">
            <view class="create-section-head"><view><text class="section-index">03</text><text class="plan-title">执行方式</text></view><text class="setting-state" :class="{ok:form.auto_run}">{{ form.auto_run ? '全自动' : '手动执行' }}</text></view>
          <checkbox-group class="auto-run-option" @change="setAutoRun"><label><checkbox value="auto" :checked="form.auto_run" color="#d7ff68" /><view><text class="auto-run-title">全自动一条龙执行</text><text class="hint">勾选后进入任务队列；AI 导演失败每 3 秒重试，成功后自动生成音频、对齐并生成视频</text></view></label></checkbox-group>
          </view>
          <view class="create-section">
            <view class="create-section-head"><view><text class="section-index">04</text><text class="plan-title">成品后期设置</text></view><text class="hint">默认配置可直接使用，需要精调时再展开</text></view>
            <view class="post-accordion create-accordion">
              <view class="post-accordion-head" @click="toggleCreatePanel('bgm')"><view><text class="auto-run-title">背景音乐</text><text class="hint">循环、淡入淡出和人声自动避让</text></view><view class="accordion-meta"><text class="accordion-status" :class="{enabled:form.bgm_enabled}">{{ form.bgm_enabled ? '已开启' : '未开启' }}</text><text class="accordion-arrow">{{ createPanels.bgm ? '▲' : '▼' }}</text></view></view>
              <view v-if="createPanels.bgm" class="post-accordion-body">
          <checkbox-group class="auto-run-option" @change="setBgmEnabled"><label><checkbox value="bgm" :checked="form.bgm_enabled" color="#d7ff68" /><view><text class="auto-run-title">视频生成后添加背景音乐</text><text class="hint">保留无配乐原视频，并使用本地 FFmpeg 自动循环、淡入淡出和人声避让。</text></view></label></checkbox-group>
              <view v-if="form.bgm_enabled" class="upload-box" :class="{selected:Boolean(bgmPath)}" @click="chooseBgm">
                <text class="upload-icon">♬</text><text>背景音乐</text><text v-if="bgmPath" class="upload-status">✓ 已选择</text><text class="hint file-name">{{ bgmFileName || '启用配乐后必选；支持 MP3、WAV、M4A、FLAC 等' }}</text>
              </view>
          <view v-if="form.bgm_enabled" class="bgm-settings">
            <view><text class="label">配乐音量 {{ Math.round(Number(form.bgm_volume || 0) * 100) }}%</text><slider :value="Number(form.bgm_volume || 0) * 100" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="form.bgm_volume=$event.detail.value/100"/></view>
            <checkbox-group @change="setBgmDucking"><label class="compact-check"><checkbox value="duck" :checked="form.bgm_ducking" color="#d7ff68" /><text>人声出现时自动降低配乐</text></label></checkbox-group>
            <view class="bgm-times"><view><text class="label">淡入秒数</text><input v-model="form.bgm_fade_in" class="field" type="digit" /></view><view><text class="label">淡出秒数</text><input v-model="form.bgm_fade_out" class="field" type="digit" /></view></view>
          </view>
              </view>
            </view>
            <view class="post-accordion create-accordion">
              <view class="post-accordion-head" @click="toggleCreatePanel('title')"><view><text class="auto-run-title">视频上方标题</text><text class="hint">从口播稿自动提取，最多三行</text></view><view class="accordion-meta"><text class="accordion-status" :class="{enabled:form.video_title_enabled}">{{ form.video_title_enabled ? '已开启' : '未开启' }}</text><text class="accordion-arrow">{{ createPanels.title ? '▲' : '▼' }}</text></view></view>
              <view v-if="createPanels.title" class="post-accordion-body">
          <checkbox-group class="auto-run-option" @change="setVideoTitleEnabled($event,form)"><label><checkbox value="title" :checked="form.video_title_enabled" color="#d7ff68" /><view><text class="auto-run-title">视频上方常驻标题</text><text class="hint">从口播稿自动提取，可编辑；从 0 秒显示到视频结束。</text></view></label></checkbox-group>
            <view v-if="form.video_title_enabled" class="video-title-editor">
              <view class="subtitle-preset-bar"><view><text class="auto-run-title">视频号顶部标题</text><text class="hint">统一标题颜色 · 88号粗体 · 黑色描边 · 距顶部10%</text></view><button class="ghost small" @click="applyChannelsTitlePreset(form,form.original_script)">应用预设</button></view>
              <view><text class="label">标题文案（最多三行，每行12字）</text><textarea v-model="form.video_title" class="textarea video-title-input" :maxlength="100" placeholder="第一行标题&#10;第二行标题&#10;第三行标题"></textarea><button class="ghost small title-regenerate" @click="form.video_title=suggestVideoTitleText(form.original_script)">从口播稿重新提取</button></view>
              <view class="subtitle-grid"><view><text class="label">字体</text><picker :range="fontOptions" @change="form.video_title_font_name=fontOptions[$event.detail.value]"><view class="field picker-field">{{ form.video_title_font_name }}</view></picker></view><view><text class="label">字号 {{ Number(form.video_title_font_size||88) }}</text><slider :value="Number(form.video_title_font_size||88)" min="48" max="140" step="1" activeColor="#d7ff68" block-size="14" @changing="form.video_title_font_size=$event.detail.value"/></view><view><text class="label">距顶部 {{ Number(form.video_title_position||10) }}%</text><slider :value="Number(form.video_title_position||10)" min="3" max="35" step="1" activeColor="#d7ff68" block-size="14" @changing="form.video_title_position=$event.detail.value"/></view><view><text class="label">黑色描边 {{ Number(form.video_title_stroke_width||4) }}</text><slider :value="Number(form.video_title_stroke_width||4)" min="0" max="8" step="0.5" activeColor="#d7ff68" block-size="14" @changing="form.video_title_stroke_width=$event.detail.value"/></view><view><text class="label">标题颜色</text><input v-model="form.video_title_primary_color" class="field color-field" maxlength="7" /></view></view>
            </view>
              </view>
            </view>
            <view class="post-accordion create-accordion">
              <view class="post-accordion-head" @click="toggleCreatePanel('subtitle')"><view><text class="auto-run-title">口播字幕</text><text class="hint">使用本地 Whisper 精确时间轴</text></view><view class="accordion-meta"><text class="accordion-status" :class="{enabled:form.subtitle_enabled}">{{ form.subtitle_enabled ? '已开启' : '未开启' }}</text><text class="accordion-arrow">{{ createPanels.subtitle ? '▲' : '▼' }}</text></view></view>
              <view v-if="createPanels.subtitle" class="post-accordion-body">
          <checkbox-group class="auto-run-option" @change="setSubtitleEnabled"><label><checkbox value="subtitle" :checked="form.subtitle_enabled" color="#d7ff68" /><view><text class="auto-run-title">视频生成后添加字幕</text><text class="hint">使用本地 Whisper 精确时间轴，保留无字幕原视频。</text></view></label></checkbox-group>
            <view v-if="form.subtitle_enabled" class="subtitle-preset-bar"><view><text class="auto-run-title">视频号口播字幕</text><text class="hint">粗体 · 64号 · 黑色描边 · 距顶部73% · 单条14字</text></view><button class="ghost small" @click="applyChannelsSubtitlePreset(form)">应用预设</button></view>
            <view v-if="form.subtitle_enabled" class="subtitle-grid">
              <view><text class="label">字体</text><picker :range="fontOptions" @change="form.subtitle_font_name=fontOptions[$event.detail.value]"><view class="field picker-field">{{ form.subtitle_font_name }}</view></picker></view>
              <checkbox-group @change="setSubtitleBold($event,form)"><label class="compact-check subtitle-bold"><checkbox value="bold" :checked="form.subtitle_font_bold" color="#d7ff68" /><text>粗体字幕</text></label></checkbox-group>
              <view><text class="label">位置</text><view class="position-options"><button v-for="item in subtitlePositions" :key="item.value" class="position-button" :class="{active:form.subtitle_position===item.value}" @click="form.subtitle_position=item.value">{{ item.label }}</button></view></view>
              <view v-if="form.subtitle_position==='custom'"><text class="label">距顶部 {{ Number(form.subtitle_custom_position||0) }}%</text><slider :value="Number(form.subtitle_custom_position||0)" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="form.subtitle_custom_position=$event.detail.value"/></view>
              <view><text class="label">字号 {{ Number(form.subtitle_font_size||60) }}</text><slider :value="Number(form.subtitle_font_size||60)" min="20" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="form.subtitle_font_size=$event.detail.value"/></view>
              <view><text class="label">单条最大字数</text><input v-model="form.subtitle_max_chars" class="field" type="number" /></view>
              <view><text class="label">文字颜色（#RRGGBB）</text><input v-model="form.subtitle_font_color" class="field color-field" maxlength="7" /><view class="color-options"><button v-for="color in subtitleColors" :key="`form-${color}`" class="color-swatch" :class="{active:String(form.subtitle_font_color||'').toUpperCase()===color}" :style="{backgroundColor:color}" :title="color" @click="form.subtitle_font_color=color"></button></view></view>
              <view><text class="label">黑色描边 {{ Number(form.subtitle_stroke_width||0) }}</text><slider :value="Number(form.subtitle_stroke_width||0)" min="0" max="8" step="0.5" activeColor="#d7ff68" block-size="14" @changing="form.subtitle_stroke_width=$event.detail.value"/></view>
            </view>
            <checkbox-group @change="setSubtitleBackground"><label class="compact-check"><checkbox value="background" :checked="form.subtitle_background_enabled" color="#d7ff68" /><text>显示半透明字幕背景</text></label></checkbox-group>
            <view v-if="form.subtitle_background_enabled" class="subtitle-grid">
              <view><text class="label">背景颜色</text><input v-model="form.subtitle_background_color" class="field color-field" maxlength="7" /></view>
              <view><text class="label">背景不透明度 {{ Number(form.subtitle_background_opacity||0) }}%</text><slider :value="Number(form.subtitle_background_opacity||0)" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="form.subtitle_background_opacity=$event.detail.value"/></view>
            </view>
              </view>
            </view>
            <view v-if="(createPanels.title||createPanels.subtitle)&&(form.video_title_enabled||form.subtitle_enabled)" class="subtitle-preview-frame"><image v-if="imagePath" class="subtitle-preview-image" :src="imagePath" mode="aspectFill"/><view class="subtitle-safe-zone">视频号界面安全区</view><view v-if="form.video_title_enabled" class="video-title-preview" :style="videoTitlePositionStyle(form)"><text v-for="(line,index) in videoTitleLines(form.video_title)" :key="`form-title-${index}`" :style="videoTitleLineStyle(form,index)">{{ line }}</text></view><view v-if="form.subtitle_enabled" class="subtitle-preview-text" :style="[subtitlePreviewStyle(form),subtitlePreviewPositionStyle(form)]"><text>{{ form.original_script.slice(0, Number(form.subtitle_max_chars||14)) || '字幕效果预览' }}</text></view></view>
          </view>
          <view class="create-section create-submit-section">
            <view class="create-section-head"><view><text class="section-index">05</text><text class="plan-title">提交检查</text></view><text class="setting-state" :class="{ok:createReady}">{{ createReady ? '可以提交' : '请补全必填项' }}</text></view>
            <view class="create-checklist"><view v-for="item in createChecks" :key="item.label" class="create-check" :class="{ok:item.ok,required:!item.ok&&item.required}"><text class="check-symbol">{{ item.ok ? '✓' : (item.required ? '!' : '•') }}</text><view><text>{{ item.label }}</text><text class="hint">{{ item.detail }}</text></view></view></view>
          <view v-if="submitting&&uploadLabel" class="upload-progress-panel"><view class="task-progress"><view :style="{width:`${uploadProgress}%`}"></view></view><text class="hint">{{ uploadLabel }} · {{ uploadProgress }}%</text></view>
          <button class="primary wide" :disabled="submitting||!createReady" @click="createProject">{{ submitting ? (uploadLabel || '正在创建任务…') : (form.auto_run ? '加入任务队列' : '创建手动任务') }}</button>
          </view>
        </view>

        <template v-if="viewMode==='projects'&&current">
          <view class="project-head panel"><view class="project-identity"><text class="eyebrow">PRODUCTION</text><input v-model="current.title" class="project-title-edit" maxlength="100" @blur="saveCurrentTitle" /><text class="hint">{{ current.id }}</text></view><view class="status-box"><text>{{ statusName(current.status) }}</text><view class="progress"><view :style="{width: `${current.progress || 0}%`}"></view></view><text class="hint">{{ durationSummary }}</text></view></view>

          <view class="project-tabs panel"><button v-for="tab in projectTabs" :key="tab.value" class="project-tab" :class="{active:projectTab===tab.value}" @click="projectTab=tab.value"><text>{{ tab.label }}</text><text v-if="tab.value==='post'&&current.has_video" class="tab-ready">●</text></button></view>
          <view v-if="current.error" class="persistent-error panel"><view><text class="error-title">{{ current.error.type || '任务执行失败' }}</text><text class="error-stage">{{ statusName(current.status) }}</text></view><text class="error-message">{{ current.error.message || current.error }}</text><view class="actions"><button class="ghost small" @click="copyError(current.error)">复制错误</button><button class="primary small" @click="navigateTo('queue')">前往队列处理</button></view></view>

          <view v-if="projectTab==='overview'" class="panel content-card source-material-card">
            <view class="section-head"><view><text class="plan-title">任务原始素材</text><text class="hint inline-hint">提交后立即可查看</text></view><button v-if="current.can_edit_original_script" class="ghost small" @click="saveOriginalScript">保存口播稿</button></view>
            <view class="source-material">
              <image v-if="current.has_image" class="source-portrait" :src="assetUrl('image')" mode="aspectFill" />
              <view class="source-script"><text class="label">原始口播稿</text><textarea v-model="current.original_script" class="textarea source-script-editor" :disabled="!current.can_edit_original_script" :maxlength="-1"></textarea><text class="hint">{{ current.can_edit_original_script ? '音频开始生成前可以修改；保存后会重新执行 AI 导演。' : '音频已经开始生成，原始口播稿已锁定。' }}</text></view>
            </view>
          </view>

          <view v-if="projectTab==='director'" class="panel content-card director-plan-card">
            <view class="section-head"><view><text class="plan-title">AI 导演方案</text><text class="hint inline-hint">{{ directorModeText }}</text></view><button v-if="current.script&&!productionComplete" class="ghost small" @click="saveDirector">保存修改</button></view>
            <view v-if="!current.script" class="director-empty"><text class="empty-title">导演方案尚未生成</text><text class="hint">点击开始分析后，这里会显示看图结论、口播稿、声音情绪和动作边界。</text><button v-if="!productionComplete" class="primary small" :disabled="isBusy" @click="run('analyze')">{{ isBusy ? '正在分析…' : '开始 AI 导演分析' }}</button></view>
            <template v-else>
              <view class="script-source-lock"><text class="analysis-label">口播内容来源</text><text>已锁定为你提供的原始口播稿；AI只设计语气、情绪和动作，不改写内容。</text></view>
              <view class="director"><image class="portrait" :src="assetUrl('image')" mode="aspectFill"/><view class="director-main">
                <view class="analysis-grid">
                  <view v-for="item in analysisDetails" :key="item.label" class="analysis-item" :class="{wide:item.wide}"><text class="analysis-label">{{ item.label }}</text><text class="analysis-value">{{ item.value || '—' }}</text></view>
                </view>
                <view class="action-columns"><view class="action-box safe"><text class="analysis-label">适合动作</text><text>{{ actionText('safe_actions') }}</text></view><view class="action-box avoid"><text class="analysis-label">避免动作</text><text>{{ actionText('avoid_actions') }}</text></view></view>
                <view class="voice-plan"><text class="analysis-label">声音建议</text><text>语速 {{ voicePlan.pace || '—' }} · 能量 {{ formatRatio(voicePlan.energy) }} · 温暖度 {{ formatRatio(voicePlan.warmth) }}</text></view>
              </view></view>
              <text class="label">最终口播稿</text><textarea v-model="current.script" class="textarea editor" :disabled="productionComplete" :maxlength="-1"></textarea>
              <view v-if="current.tts_engine!=='indextts2_voice_clone'"><text class="subheading">声音情绪</text><view class="emotion-grid"><view v-for="name in emotionNames" :key="name" class="emotion"><view class="emotion-head"><text>{{ name }}</text><text>{{ Number(current.emotion?.[name] || 0).toFixed(2) }}</text></view><slider :disabled="productionComplete" :value="Number(current.emotion?.[name] || 0) * 100" min="0" max="100" activeColor="#d7ff68" block-size="14" @changing="setEmotion(name, $event.detail.value)"/></view></view></view>
              <view v-if="current.segments?.length" class="segment-summary"><text class="subheading">每 4 秒动作方案</text><view class="summary-list"><view v-for="segment in current.segments" :key="`summary-${segment.index}`" class="summary-item"><text class="summary-time">{{ formatTime(segment.start) }}–{{ formatTime(segment.end) }}</text><text class="summary-action">{{ segment.action_prompt }}</text></view></view></view>
            </template>
          </view>

          <view v-if="projectTab==='overview'&&!productionComplete" class="steps"><view class="step panel"><text class="step-no">01</text><view><text class="step-title">AI 导演分析</text><text class="hint">构图、文案与声音情绪</text></view><button class="primary small" :disabled="isBusy" @click="run('analyze')">开始分析</button></view><view class="step panel"><text class="step-no">02</text><view><text class="step-title">声音与时间轴</text><text class="hint">IndexTTS2 + 本地 Whisper</text></view><button class="primary small" :disabled="isBusy || !current.script" @click="run('audio')">生成音频</button></view><view class="step panel"><text class="step-no">03</text><view><text class="step-title">InfiniteTalk 视频</text><text class="hint">动态火车节连续生成</text></view><button class="primary small" :disabled="isBusy || !current.has_audio || !current.segments?.length" @click="run('video')">生成视频</button></view></view>

          <view v-if="current.has_audio&&projectTab==='audio'" class="panel content-card">
            <view class="section-head"><view><text>声音与表演时间轴</text><text class="hint inline-hint">{{ alignmentSummary }}</text></view><view v-if="!productionComplete" class="actions"><button class="ghost small" @click="run('align')">重新对齐</button><button class="ghost small" @click="saveSegments">保存动作</button></view></view>
            <view class="audio-player">
              <button class="primary small play-button" @click="toggleAudio">{{ audioPlaying ? '暂停' : '播放音频' }}</button>
              <text class="audio-time">{{ formatTime(audioCurrent) }} / {{ formatTime(audioTotal || current.audio_duration || 0) }}</text>
              <slider class="audio-slider" :value="audioCurrent" :max="Math.max(1, audioTotal || Number(current.audio_duration || 0))" min="0" step="0.1" activeColor="#d7ff68" block-size="14" @change="seekAudio"/>
            </view>
            <view v-if="current.alignment?.audio_quality" class="quality-card" :class="`quality-${current.alignment.audio_quality.status}`">
              <view class="quality-head"><text class="subheading quality-title">音频中断检查</text><text class="quality-status">{{ current.alignment.audio_quality.status }}</text></view>
              <text class="quality-summary">{{ current.alignment.audio_quality.summary }}</text>
              <view v-for="(issue, issueIndex) in current.alignment.audio_quality.issues || []" :key="`issue-${issueIndex}`" class="quality-issue" @click="seekToTime(issue.time)">
                <text class="issue-time">{{ issue.time == null ? '全局' : formatTime(issue.time) }}</text>
                <text>{{ issue.reason }}</text>
              </view>
              <text v-if="current.alignment.audio_quality.limitation" class="hint quality-limit">{{ current.alignment.audio_quality.limitation }}</text>
            </view>
            <view v-if="current.alignment?.sentences?.length" class="sentence-card">
              <text class="subheading">逐句精确时间</text>
              <view v-for="sentence in current.alignment.sentences" :key="`sentence-${sentence.index}`" class="sentence-row" @click="seekToTime(sentence.start)">
                <text class="sentence-time">{{ formatTime(sentence.start) }}–{{ formatTime(sentence.end) }}</text>
                <text class="sentence-text">{{ sentence.text }}</text>
                <text class="hint">句前停顿 {{ Number(sentence.pause_before || 0).toFixed(2) }}s · {{ Number(sentence.chars_per_second || 0).toFixed(2) }} 字/秒</text>
              </view>
            </view>
            <view class="segments"><view v-for="segment in current.segments" :key="segment.index" class="segment"><view class="segment-time"><text>{{ formatTime(segment.start) }}–{{ formatTime(segment.end) }}</text><text class="hint">第 {{ segment.index + 1 }} 节</text><text v-if="segment.starts_mid_sentence" class="flow">↳ 承接上句</text><text v-if="segment.ends_mid_sentence" class="flow">下节继续 ↪</text></view><view class="segment-body"><text class="spoken">窗口口播：{{ segment.spoken_text }}</text><view v-for="event in segment.speech_events || []" :key="`${event.local_start}-${event.text}`" class="event"><text class="event-time">{{ Number(event.local_start).toFixed(1) }}–{{ Number(event.local_end).toFixed(1) }}s</text><text>{{ event.text }}</text><text class="hint full-sentence">完整语句：{{ event.full_sentence }}</text></view><textarea v-model="segment.action_prompt" class="textarea action-editor" :disabled="productionComplete" :maxlength="-1"></textarea></view></view></view>
          </view>

          <view v-if="current.has_video&&projectTab==='post'" class="panel content-card post-workbench">
            <view class="section-head"><text>成品视频</text><view class="actions"><button v-if="current.has_raw_video" class="ghost small" @click="downloadVideo('video_raw')">下载无字幕原片</button><button v-if="current.has_subtitle_video" class="ghost small" @click="downloadVideo('video_subtitled')">下载字幕版</button><button v-if="current.has_bgm_video" class="ghost small" @click="downloadVideo('video_bgm')">下载配乐成片</button></view></view>
            <view v-if="!videoSource" class="video-lazy"><text class="video-lazy-title">视频尚未加载</text><text class="hint">切换项目不会下载视频，点击播放后才开始加载。</text><view class="actions"><button class="primary small" @click="loadVideo('video')">播放{{ current.has_bgm_video ? '配乐版' : '视频' }}</button><button v-if="current.has_raw_video&&current.has_bgm_video" class="ghost small" @click="loadVideo('video_raw')">播放无配乐版</button></view></view><video v-else class="video" :src="videoSource" controls autoplay @error="videoLoadError"></video>
            <view v-if="current.has_raw_video" class="subtitle-settings subtitle-editor">
              <view class="post-accordion">
                <view class="post-accordion-head" @click="togglePostPanel('title')"><view><text class="auto-run-title">视频上方标题</text><text class="hint">最多三行，可在成片后单独开启或调整</text></view><view class="accordion-meta"><text class="accordion-status" :class="{enabled:current.video_title_enabled}">{{ isBusy ? '处理中' : (current.video_title_enabled ? '已开启' : '未开启') }}</text><text class="accordion-arrow">{{ postPanels.title ? '▲' : '▼' }}</text></view></view>
                <view v-if="postPanels.title" class="post-accordion-body">
              <view class="subtitle-preset-bar"><view><text class="auto-run-title">视频号顶部标题</text><text class="hint">常驻最多三行标题与逐句字幕一次烧录，不重复压制</text></view><button class="ghost small" @click="applyChannelsTitlePreset(current,current.script||current.original_script)">应用预设</button></view>
              <checkbox-group @change="setCurrentVideoTitleEnabled"><label class="compact-check"><checkbox value="title" :checked="current.video_title_enabled" color="#d7ff68" /><text>启用视频顶部常驻标题</text></label></checkbox-group>
              <view v-if="current.video_title_enabled" class="video-title-editor"><view><text class="label">标题文案（最多三行，每行12字）</text><textarea v-model="current.video_title" class="textarea video-title-input" :maxlength="100"></textarea><button class="ghost small title-regenerate" @click="current.video_title=suggestVideoTitleText(current.script||current.original_script)">从口播稿重新提取</button></view><view class="subtitle-grid"><view><text class="label">字体</text><picker :range="fontOptions" @change="current.video_title_font_name=fontOptions[$event.detail.value]"><view class="field picker-field">{{ current.video_title_font_name }}</view></picker></view><view><text class="label">字号 {{ Number(current.video_title_font_size||88) }}</text><slider :value="Number(current.video_title_font_size||88)" min="48" max="140" step="1" activeColor="#d7ff68" block-size="14" @changing="current.video_title_font_size=$event.detail.value"/></view><view><text class="label">距顶部 {{ Number(current.video_title_position||10) }}%</text><slider :value="Number(current.video_title_position||10)" min="3" max="35" step="1" activeColor="#d7ff68" block-size="14" @changing="current.video_title_position=$event.detail.value"/></view><view><text class="label">黑色描边 {{ Number(current.video_title_stroke_width||4) }}</text><slider :value="Number(current.video_title_stroke_width||4)" min="0" max="8" step="0.5" activeColor="#d7ff68" block-size="14" @changing="current.video_title_stroke_width=$event.detail.value"/></view><view><text class="label">标题颜色</text><input v-model="current.video_title_primary_color" class="field color-field" maxlength="7" /></view></view></view>
                </view>
              </view>
              <view class="post-accordion">
                <view class="post-accordion-head" @click="togglePostPanel('subtitle')"><view><text class="auto-run-title">口播字幕</text><text class="hint">可在成片后开启，不会重新生成数字人视频</text></view><view class="accordion-meta"><text class="accordion-status" :class="{enabled:current.subtitle_enabled}">{{ isBusy ? '处理中' : (current.subtitle_enabled ? '已开启' : '未开启') }}</text><text class="accordion-arrow">{{ postPanels.subtitle ? '▲' : '▼' }}</text></view></view>
                <view v-if="postPanels.subtitle" class="post-accordion-body">
              <view v-if="current.subtitle_enabled" class="subtitle-preset-bar"><view><text class="auto-run-title">视频号口播字幕</text><text class="hint">应用后点击下方按钮重新生成字幕版</text></view><button class="ghost small" @click="applyChannelsSubtitlePreset(current)">应用预设</button></view>
              <checkbox-group @change="setCurrentSubtitleEnabled"><label class="compact-check"><checkbox value="subtitle" :checked="current.subtitle_enabled" color="#d7ff68" /><text>启用成片字幕</text></label></checkbox-group>
              <view v-if="current.subtitle_enabled" class="subtitle-grid">
                <view><text class="label">字体</text><picker :range="fontOptions" @change="current.subtitle_font_name=fontOptions[$event.detail.value]"><view class="field picker-field">{{ current.subtitle_font_name }}</view></picker></view>
                <checkbox-group @change="setSubtitleBold($event,current)"><label class="compact-check subtitle-bold"><checkbox value="bold" :checked="current.subtitle_font_bold" color="#d7ff68" /><text>粗体字幕</text></label></checkbox-group>
                <view><text class="label">位置</text><view class="position-options"><button v-for="item in subtitlePositions" :key="`current-${item.value}`" class="position-button" :class="{active:current.subtitle_position===item.value}" @click="current.subtitle_position=item.value">{{ item.label }}</button></view></view>
                <view v-if="current.subtitle_position==='custom'"><text class="label">距顶部 {{ Number(current.subtitle_custom_position||0) }}%</text><slider :value="Number(current.subtitle_custom_position||0)" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="current.subtitle_custom_position=$event.detail.value"/></view>
                <view><text class="label">字号 {{ Number(current.subtitle_font_size||60) }}</text><slider :value="Number(current.subtitle_font_size||60)" min="20" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="current.subtitle_font_size=$event.detail.value"/></view>
                <view><text class="label">单条最大字数</text><input v-model="current.subtitle_max_chars" class="field" type="number" /></view>
                <view><text class="label">文字颜色（#RRGGBB）</text><input v-model="current.subtitle_font_color" class="field color-field" maxlength="7" /><view class="color-options"><button v-for="color in subtitleColors" :key="`current-${color}`" class="color-swatch" :class="{active:String(current.subtitle_font_color||'').toUpperCase()===color}" :style="{backgroundColor:color}" :title="color" @click="current.subtitle_font_color=color"></button></view></view>
                <view><text class="label">黑色描边 {{ Number(current.subtitle_stroke_width||0) }}</text><slider :value="Number(current.subtitle_stroke_width||0)" min="0" max="8" step="0.5" activeColor="#d7ff68" block-size="14" @changing="current.subtitle_stroke_width=$event.detail.value"/></view>
              </view>
              <checkbox-group v-if="current.subtitle_enabled" @change="setCurrentSubtitleBackground"><label class="compact-check"><checkbox value="background" :checked="current.subtitle_background_enabled" color="#d7ff68" /><text>显示半透明字幕背景</text></label></checkbox-group>
              <view v-if="current.subtitle_enabled&&current.subtitle_background_enabled" class="subtitle-grid"><view><text class="label">背景颜色</text><input v-model="current.subtitle_background_color" class="field color-field" maxlength="7" /></view><view><text class="label">背景不透明度 {{ Number(current.subtitle_background_opacity||0) }}%</text><slider :value="Number(current.subtitle_background_opacity||0)" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="current.subtitle_background_opacity=$event.detail.value"/></view></view>
                </view>
              </view>
              <view v-if="current.subtitle_enabled||current.video_title_enabled" class="subtitle-preview-frame"><image v-if="current.has_image" class="subtitle-preview-image" :src="assetUrl('image')" mode="aspectFill"/><view class="subtitle-safe-zone">视频号界面安全区</view><view v-if="current.video_title_enabled" class="video-title-preview" :style="videoTitlePositionStyle(current)"><text v-for="(line,index) in videoTitleLines(current.video_title)" :key="`current-title-${index}`" :style="videoTitleLineStyle(current,index)">{{ line }}</text></view><view v-if="current.subtitle_enabled" class="subtitle-preview-text" :style="[subtitlePreviewStyle(current),subtitlePreviewPositionStyle(current)]"><text>{{ String(current.script||current.original_script||'字幕效果预览').slice(0, Number(current.subtitle_max_chars||14)) }}</text></view></view>
              <button class="primary wide" :disabled="isBusy" @click="saveSubtitleAndRun">{{ (current.subtitle_enabled||current.video_title_enabled) ? (current.has_subtitle_video ? '重新生成标题/字幕版' : '生成标题/字幕版') : '保存并关闭标题与字幕' }}</button>
            </view>
            <view v-if="current.has_raw_video" class="bgm-editor">
              <view class="section-head"><view><text class="subheading quality-title">背景音乐后期</text><text class="hint inline-hint">更换或调整配乐不会重新生成数字人视频</text></view><button class="ghost small" @click="chooseProjectBgm">更换音乐</button></view>
              <view><text class="label">配乐音量 {{ Math.round(Number(current.bgm_volume || 0) * 100) }}%</text><slider :value="Number(current.bgm_volume || 0) * 100" min="0" max="100" step="1" activeColor="#d7ff68" block-size="14" @changing="current.bgm_volume=$event.detail.value/100"/></view>
              <checkbox-group @change="setCurrentBgmDucking"><label class="compact-check"><checkbox value="duck" :checked="current.bgm_ducking" color="#d7ff68" /><text>人声出现时自动降低配乐</text></label></checkbox-group>
              <view class="bgm-times"><view><text class="label">淡入秒数</text><input v-model="current.bgm_fade_in" class="field" type="digit" /></view><view><text class="label">淡出秒数</text><input v-model="current.bgm_fade_out" class="field" type="digit" /></view></view>
              <button class="primary wide" :disabled="isBusy||!current.has_bgm" @click="saveBgmAndRun">{{ current.has_bgm_video ? '重新生成配乐版' : '生成配乐版' }}</button>
            </view>
          </view>
          <view v-if="current.error" class="error">{{ current.error.type }}：{{ current.error.message }}</view>
        </template>
      </view>
    </view>
  </view>
</template>

<script>
import { fileUrl, getApiBase, request, upload } from '../../utils/api.js'

const BUSY = new Set(['QUEUE_WAITING','UPLOADING_ASSETS','ANALYZE_QUEUED','ANALYZING_IMAGE','ANALYSIS_RETRYING','AUDIO_QUEUED','UPLOADING_REFERENCE_AUDIO','GENERATING_AUDIO','ALIGN_QUEUED','ALIGNING_SPEECH','PLANNING_ACTIONS','VIDEO_QUEUED','UPLOADING_VIDEO_ASSETS','GENERATING_VIDEO','BGM_QUEUED','MIXING_BGM'])
const STATUS = {CREATED:'已创建',QUEUE_WAITING:'等待队列执行',UPLOADING_ASSETS:'正在上传任务素材',QUEUE_CANCELLED:'队列任务已取消',ANALYZE_QUEUED:'等待分析',ANALYZING_IMAGE:'AI 正在分析图片',ANALYSIS_RETRYING:'AI 导演失败，3 秒后重试',SCRIPT_READY:'导演方案已就绪',AUDIO_QUEUED:'等待生成音频',UPLOADING_REFERENCE_AUDIO:'正在上传参考音色',GENERATING_AUDIO:'IndexTTS2 正在生成',ALIGN_QUEUED:'等待语音对齐',ALIGNING_SPEECH:'Whisper 正在对齐',PLANNING_ACTIONS:'正在按时间轴设计动作',PLAN_READY:'音频与动作计划就绪',VIDEO_QUEUED:'等待生成视频',UPLOADING_VIDEO_ASSETS:'正在上传视频素材',GENERATING_VIDEO:'InfiniteTalk 正在生成',VIDEO_READY:'无配乐视频已就绪',BGM_QUEUED:'等待添加配乐',MIXING_BGM:'正在添加背景音乐',BGM_ERROR:'配乐失败，原视频可用',COMPLETED:'制作完成',ERROR:'生成失败'}
const TASK_STATUS = {QUEUED:'等待执行',RUNNING:'正在执行',COMPLETED:'已完成',FAILED:'失败',CANCELLED:'已取消'}
const TASK_STAGE = {WAITING:'等待资源',UPLOADING_ASSETS:'上传任务素材',RECOVERING:'恢复任务',STARTING:'准备开始',ANALYZING:'AI 导演分析',ANALYSIS_RETRYING:'AI 导演将在 3 秒后重试',GENERATING_AUDIO:'音频与对齐',GENERATING_VIDEO:'视频生成',COMPLETED:'生产完成',FAILED:'执行失败',CANCELLED:'已取消'}
for(const value of ['SUBTITLE_QUEUED','BURNING_SUBTITLES'])BUSY.add(value)
Object.assign(STATUS,{VIDEO_READY:'原始视频已就绪',SUBTITLE_QUEUED:'等待生成标题/字幕',BURNING_SUBTITLES:'正在烧录标题/字幕',SUBTITLE_READY:'标题/字幕版已就绪',BGM_ERROR:'配乐失败，前一版本可用'})
Object.assign(TASK_STAGE,{BURNING_SUBTITLES:'标题/字幕烧录',MIXING_BGM:'背景音乐混音'})

export default {
  data() { return {viewMode:'create',projectTab:'overview',realtimeConnected:false,uploadProgress:0,uploadLabel:'',health:{},appSettings:{comfy_url:''},settingsSaving:false,availableFonts:[],projects:[],tasks:[],current:null,poll:null,queuePoll:null,submitting:false,comfyChecking:false,comfyCheckResult:'',comfyCheckOk:false,imagePath:'',imageFileName:'',voicePath:'',voiceFileName:'',emotionVoicePath:'',emotionVoiceFileName:'',bgmPath:'',bgmFileName:'',audioPlaying:false,audioCurrent:0,audioTotal:0,audioSource:'',videoSource:'',lastSuggestedVideoTitle:'',createPanels:{title:false,subtitle:false,bgm:false},postPanels:{title:false,subtitle:false},emotionNames:['Happy','Angry','Sad','Fear','Hate','Low','Surprise','Neutral'],form:{title:'健康管理口播',tts_engine:'indextts2_legacy',original_script:'百万亿健康管理蓝海市场，机遇就在眼前。友福同享智能科技有限公司，专注一站式AI健康管理五年多。现面向全国招募社区健康服务中心项目合伙人。如果你对健康管理感兴趣，想低门槛撬动高价值、高利润项目，友福就是你的最佳选择。友福三大核心优势，帮合伙人轻松开拓市场。',auto_run:true,bgm_enabled:false,bgm_volume:0.25,bgm_ducking:true,bgm_fade_in:1.5,bgm_fade_out:2}} },
