    createChecks(){const clone=this.form.tts_engine==='indextts2_voice_clone',checks=[{label:'口播文案',ok:Boolean(String(this.form.original_script||'').trim()),required:true,detail:String(this.form.original_script||'').trim()?'已填写':'必填'},{label:'数字人图片',ok:Boolean(this.imagePath),required:false,detail:this.imagePath?(this.imageFileName||'已选择'):'未选择时使用默认图片'},{label:'音色参考音频',ok:Boolean(this.voicePath),required:false,detail:this.voicePath?(this.voiceFileName||'已选择'):'未选择时使用默认音色'}];if(clone)checks.push({label:'情感参考音频',ok:Boolean(this.emotionVoicePath),required:true,detail:this.emotionVoicePath?(this.emotionVoiceFileName||'已选择'):'当前音频流程必填'});if(this.form.bgm_enabled)checks.push({label:'背景音乐',ok:Boolean(this.bgmPath),required:true,detail:this.bgmPath?(this.bgmFileName||'已选择'):'已开启配乐，请选择文件'});return checks},
