    async createProject(){this.uploadProgress=0;this.uploadLabel='';if(!this.form.original_script.trim()){this.toast('请填写口播文案');return}const needsEmotion=this.form.tts_engine==='indextts2_voice_clone';if(needsEmotion&&!this.emotionVoicePath){this.toast('IndexTTS2 音色与情感克隆版请选择情感参考音频');return}if(this.form.bgm_enabled&&!this.bgmPath){this.toast('启用视频配乐后请选择背景音乐');return}const autoRun=Boolean(this.form.auto_run);let task=null;this.submitting=true;try{const createPayload={...this.form,expect_image_upload:Boolean(this.imagePath),expect_voice_upload:Boolean(this.voicePath),expect_emotion_voice_upload:Boolean(this.emotionVoicePath),expect_bgm_upload:Boolean(this.bgmPath)};let p=await request('/api/projects/default',{method:'POST',data:createPayload});if(autoRun){task=await request(`/api/projects/${p.id}/enqueue`,{method:'POST'});await this.loadTasks()}try{if(this.imagePath){this.uploadLabel='正在上传数字人图片';p=await upload(`/api/projects/${p.id}/assets/image`,this.imagePath,'file',value=>this.uploadProgress=value)}if(this.voicePath){this.uploadLabel='正在上传参考音色';p=await upload(`/api/projects/${p.id}/assets/voice`,this.voicePath,'file',value=>this.uploadProgress=value)}if(this.emotionVoicePath){this.uploadLabel='正在上传情感音频';p=await upload(`/api/projects/${p.id}/assets/emotion_voice`,this.emotionVoicePath,'file',value=>this.uploadProgress=value)}if(this.bgmPath){this.uploadLabel='正在上传背景音乐';p=await upload(`/api/projects/${p.id}/assets/bgm`,this.bgmPath,'file',value=>this.uploadProgress=value)}if(!p.has_image||!p.has_voice||(needsEmotion&&!p.has_emotion_voice)||(this.form.bgm_enabled&&!p.has_bgm))throw new Error('图片、音频或背景音乐素材未上传成功')}catch(uploadError){if(task)try{await request(`/api/tasks/${task.id}/cancel`,{method:'POST'})}catch(_){}throw uploadError}if(autoRun)this.current=null;else this.current=p;this.imagePath='';this.imageFileName='';this.voicePath='';this.voiceFileName='';this.emotionVoicePath='';this.emotionVoiceFileName='';this.bgmPath='';this.bgmFileName='';await Promise.all([this.loadProjects(),this.loadTasks()]);if(autoRun)this.toast('任务已入队，素材上传完成','success');else this.toast('项目已创建，请按步骤手动操作','success')}catch(e){this.toast(e.message)}finally{this.submitting=false;this.uploadProgress=0;this.uploadLabel=''}},
    async cancelTask(task){try{await request(`/api/tasks/${task.id}/cancel`,{method:'POST'});await this.loadTasks();this.toast('任务已取消','success')}catch(error){this.toast(error.message)}},
